<h1><?= te('Account security') ?></h1><p class="sub"><?= te('Protect your account with an authenticator and manage active sessions.') ?></p>
<?php if($recoveryCodes): ?><div class="card"><h2><?= te('Save your recovery codes now') ?></h2><p><?= te('Each code works once. These codes are displayed only once; keep them somewhere private.') ?></p><?php foreach($recoveryCodes as $code): ?><p><code class="recovery-code"><?= e($code) ?></code></p><?php endforeach; ?></div><?php endif; ?>
<div class="card"><h2><?= te('Two-step verification') ?></h2>
<?php if(!$encryptionReady): ?><p><?= te('Configure a 32-byte encryption key.') ?></p><?php elseif($enabled): ?>
<p><?= te('Two-step verification enabled.') ?></p><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="disable"><label><?= te('Current password') ?><input name="password" type="password" required autocomplete="current-password"></label><label><?= te('Authenticator code') ?><input name="code" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"></label><button class="btn"><?= te('Disable') ?></button></form>
<?php elseif($setup): ?><p><?= te('Add this setup key to your authenticator, then verify the six-digit code.') ?></p><code style="overflow-wrap:anywhere"><?= e($setup['secret']) ?></code><p><?= te('Account') ?>: <?= e(user()['email']) ?> · <?= e($config['app_name']) ?></p><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="enable"><label><?= te('Current password') ?><input name="password" type="password" required autocomplete="current-password"></label><label><?= te('Authenticator code') ?><input name="code" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"></label><button class="btn"><?= te('Enable') ?></button></form>
<?php else: ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="start"><label><?= te('Current password') ?><input name="password" type="password" required autocomplete="current-password"></label><button class="btn"><?= te('Set up authenticator') ?></button></form><?php endif; ?></div>
<div class="card"><h2><?= te('Active sessions') ?></h2><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="revoke"><label><?= te('Current password') ?><input name="password" type="password" required autocomplete="current-password"></label><button class="btn ghost"><?= te('Sign out other sessions') ?></button></form></div>
